python3 - <<'PY'
import os, zipfile, shutil, tempfile
from xml.etree import ElementTree as ET
import openpyxl

OUT='/root/output/result.xlsx'

# Recompute computed values from the workbook with formulas (not data_only)
wb=openpyxl.load_workbook(OUT, data_only=False)
ws_task=wb['Task']
ws_data=wb['Data']

years=[ws_task.cell(row=10,column=c).value for c in range(8,13)]
# find header row in Data matching years
header_row=None
for r in range(1,51):
    cand=[ws_data.cell(row=r,column=c).value for c in range(8,13)]
    if cand==years:
        header_row=r
        break
assert header_row is not None

series_start,series_end=21,38

data_map={}
for r in range(series_start,series_end+1):
    code=ws_data[f'D{r}'].value
    for c,year in zip(range(8,13), years):
        data_map[(code,year)]=ws_data.cell(row=r,column=c).value

def lookup(code,year):
    return data_map[(code,year)]

def percentile_inc(vals,k):
    s=sorted(vals)
    n=len(s)
    if n==1:
        return float(s[0])
    r=(n-1)*k
    lo=int(r)
    hi=min(lo+1,n-1)
    frac=r-lo
    return float(s[lo])*(1-frac)+float(s[hi])*frac

# Determine stats mapping from labels
label_to_kind={
    'minimum':'min','maximum':'max','median':'median','simple mean':'avg','25th percentile':'p25','75th percentile':'p75'
}
row_kind={}
for r in range(42,48):
    lab=str(ws_task[f'E{r}'].value).strip().lower()
    row_kind[r]=label_to_kind[lab]

# Identify formula cells we filled
from openpyxl.utils import get_column_letter
formula_cells=set()
for r in list(range(12,18))+list(range(19,25))+list(range(26,32))+list(range(35,41))+list(range(42,48))+[50]:
    for col in range(8,13):
        formula_cells.add(f'{get_column_letter(col)}{r}')

computed={}
# lookup blocks
for r in range(12,18):
    code=ws_task[f'D{r}'].value
    for col,year in zip(range(8,13), years):
        computed[f'{get_column_letter(col)}{r}']=lookup(code,year)
for r in range(19,25):
    code=ws_task[f'D{r}'].value
    for col,year in zip(range(8,13), years):
        computed[f'{get_column_letter(col)}{r}']=lookup(code,year)
for r in range(26,32):
    code=ws_task[f'D{r}'].value
    for col,year in zip(range(8,13), years):
        computed[f'{get_column_letter(col)}{r}']=lookup(code,year)

# net buffers
for r in range(35,41):
    fund_code=ws_task[f'D{r-23}'].value
    opex_code=ws_task[f'D{r-16}'].value
    base_code=ws_task[f'D{r-9}'].value
    for col,year in zip(range(8,13), years):
        fund=float(lookup(fund_code,year))
        opex=float(lookup(opex_code,year))
        base=float(lookup(base_code,year))
        computed[f'{get_column_letter(col)}{r}']=(fund-opex)/base*100.0

# stats
for col in range(8,13):
    colL=get_column_letter(col)
    buffers=[computed[f'{colL}{r}'] for r in range(35,41)]
    for r,kind in row_kind.items():
        if kind=='min':
            v=min(buffers)
        elif kind=='max':
            v=max(buffers)
        elif kind=='median':
            s=sorted(buffers); v=(s[2]+s[3])/2.0
        elif kind=='avg':
            v=sum(buffers)/6.0
        elif kind=='p25':
            v=percentile_inc(buffers,0.25)
        elif kind=='p75':
            v=percentile_inc(buffers,0.75)
        computed[f'{colL}{r}']=v

# weighted mean
for col,year in zip(range(8,13), years):
    colL=get_column_letter(col)
    bufs=[computed[f'{colL}{r}'] for r in range(35,41)]
    weights=[float(computed[f'{colL}{r}']) for r in range(26,32)]
    denom=sum(weights)
    computed[f'{colL}50']=sum(b*w for b,w in zip(bufs,weights))/denom

# Inject cached values into correct Task xml
sheet_path='xl/worksheets/sheet1.xml'

with zipfile.ZipFile(OUT,'r') as zin:
    tmp_fd,tmp_path=tempfile.mkstemp(suffix='.xlsx')
    os.close(tmp_fd)
    with zipfile.ZipFile(tmp_path,'w',compression=zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data=zin.read(item.filename)
            if item.filename==sheet_path:
                ET.register_namespace('', 'http://schemas.openxmlformats.org/spreadsheetml/2006/main')
                ET.register_namespace('r', 'http://schemas.openxmlformats.org/officeDocument/2006/relationships')
                root=ET.fromstring(data)
                ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                sheetData=root.find('m:sheetData',ns)
                # build cell lookup
                cell_by_ref={}
                for row in sheetData.findall('m:row',ns):
                    for c in row.findall('m:c',ns):
                        ref=c.attrib.get('r')
                        if ref:
                            cell_by_ref[ref]=c
                updated=0
                for addr in formula_cells:
                    c=cell_by_ref.get(addr)
                    if c is None:
                        raise KeyError(f'missing cell {addr} in xml')
                    # set cached value
                    v=c.find('m:v',ns)
                    if v is None:
                        v=ET.SubElement(c,'{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
                    v.text=str(float(computed[addr]))
                    # ensure type numeric (omit t)
                    if 't' in c.attrib:
                        del c.attrib['t']
                    updated+=1
                data=ET.tostring(root, encoding='utf-8', xml_declaration=True)
                print('updated', updated, 'cells in xml')
            zout.writestr(item, data)

shutil.move(tmp_path, OUT)

# Validate cached values are visible
wb_do=openpyxl.load_workbook(OUT, data_only=True)
ws=wb_do['Task']
print('data_only H12,H35,H42,H50:', ws['H12'].value, ws['H35'].value, ws['H42'].value, ws['H50'].value)
print('data_only L50:', ws['L50'].value)
PY

